INSERT INTO announcements (id, site_id, title, content, priority, published_at, created_by, created_at, updated_at) VALUES ('bd3e9e9e-0db2-4abc-8bd9-e77e74d51ba3', '24204ebd-d20f-4920-8a5c-6ab825b44e39', 'Ortak Alan Temizliği ve Çöp Toplama Saatleri', 'Ortak alanların hijyeni ve düzeni açısından çöp toplama saatleri her akşam 19:30 - 20:30 arasındadır. Belirtilen saatler dışında kat hollerine çöp bırakılmaması ve geri dönüştürülebilir atıkların ayrıştırılması önemle rica olunur.', 'normal', '2026-08-20 07:15:00+00', '52d5d994-9fa6-4667-9556-fcbc9b71aff1', '2026-08-20 07:15:00+00', '2026-10-06 10:17:00.64255+00');
INSERT INTO announcements (id, site_id, title, content, priority, published_at, created_by, created_at, updated_at) VALUES ('e3b31caa-c2a8-45a2-88f9-f44a8d8f7e22', '24204ebd-d20f-4920-8a5c-6ab825b44e39', 'Asansör Yıllık Yeşil Etiket Periyodik Kontrolü Tamamlandı', 'A ve B blok asansörlerimizin A tipi akredite muayene kuruluşu tarafından gerçekleştirilen yıllık periyodik kontrolleri başarıyla tamamlanmış olup YEŞİL ETİKET (Kusursuz) yenilemesi yapılmıştır. Tüm sakinlerimize güvenli kullanımlar dileriz.', 'normal', '2026-09-12 08:30:00+00', '52d5d994-9fa6-4667-9556-fcbc9b71aff1', '2026-09-12 08:30:00+00', '2026-10-06 10:17:00.642225+00');
INSERT INTO announcements (id, site_id, title, content, priority, published_at, created_by, created_at, updated_at) VALUES ('ad7a0d36-ca6f-4121-b937-333f1a017f52', '24204ebd-d20f-4920-8a5c-6ab825b44e39', '2026 Yılı Olağan Kat Malikleri Genel Kurul Toplantısı', 'Sitemizin 2026 yılı Olağan Genel Kurul toplantısı 18 Ekim 2026 Pazar günü saat 14:00''te sitemiz sosyal tesis toplantı salonunda gerçekleştirilecektir. Çoğunluk sağlanamadığı takdirde ikinci toplantı 25 Ekim 2026 Pazar günü aynı yer ve saatte yapılacaktır. Toplantı gündemi ve denetim raporu blok panolarına asılmıştır.', 'important', '2026-10-01 06:00:00+00', '52d5d994-9fa6-4667-9556-fcbc9b71aff1', '2026-10-01 06:00:00+00', '2026-10-06 10:17:00.641733+00');
